const ctx = $('Find Live Booking').first().json;
const alts = $('Find Alternates').all().map(i => i.json);

if (!ctx || !ctx.BOOKING_ID) {
  throw new Error('no live CONFIRMED booking found -- run Act 1 first, or the demo data was reset');
}
if (alts.length === 0) {
  throw new Error('no alternate vendors for ' + ctx.INDUSTRY + '/' + ctx.SERVICE_TYPE);
}

const n = (v) => v === null || v === undefined ? 0 : Number(v);

// One line per candidate, with the cost delta spelled out. Handing the model a raw
// table invites it to just pick the top-rated row and say so; naming the tradeoff in
// dollars is what produces reasoning worth projecting.
const lines = alts.map(function (a, i) {
  const delta = n(a.COST_PER_UNIT) - n(ctx.COST);
  const sign = delta >= 0 ? '+' : '-';
  return (i + 1) + '. ' + a.VENDOR_NAME + ' (id ' + a.VENDOR_ID + ') -- rating '
    + n(a.RATING).toFixed(1) + ', $' + n(a.COST_PER_UNIT).toLocaleString()
    + ' per unit (' + sign + '$' + Math.abs(delta).toLocaleString()
    + ' vs the vendor that withdrew), capacity ' + n(a.CAPACITY);
}).join('\n');

return [{ json: {
  booking_id: ctx.BOOKING_ID,
  engagement_id: ctx.ENGAGEMENT_ID,
  client_name: ctx.CLIENT_NAME,
  engagement_name: ctx.ENGAGEMENT_NAME,
  service_type: ctx.SERVICE_TYPE,
  declined_vendor: ctx.VENDOR_NAME,
  declined_cost: n(ctx.COST),
  declined_rating: n(ctx.RATING),
  budget_variance: n(ctx.BUDGET_VARIANCE),
  candidate_count: alts.length,
  candidates: lines
} }];

const inner = $input.first().json;
const textPart = inner.content && inner.content[0] ? inner.content[0].text : (inner.text || inner.output || '');
const m = String(textPart).match(/\{[\s\S]*\}/);
if (!m) { throw new Error('agent returned no JSON: ' + String(textPart).slice(0, 300)); }
const d = JSON.parse(m[0]);

const brief = $('Brief the Agent').first().json;
const ctx = $('Find Live Booking').first().json;

// CHANGE THIS BEFORE THE DRESS REHEARSAL.
// On the night the approval must land on the CEO's phone, not Jim's -- Jim is on stage
// and cannot tap it. Set to the CEO's address and re-publish.
const APPROVER = 'jim.brown@aigs.com';

// The Code node sandbox does not expose the `crypto` global.
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
  const r = Math.random() * 16 | 0;
  const v = c === 'x' ? r : ((r & 0x3) | 0x8);
  return v.toString(16);
});
const q = (v) => (v === null || v === undefined) ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'";
const num = (v) => (v === null || v === undefined || v === '' || isNaN(Number(v))) ? '0' : String(Number(v));

if (!d.chosen_vendor_id) { throw new Error('agent chose no vendor id'); }
if (d.chosen_vendor_name === brief.declined_vendor) {
  throw new Error('agent re-picked the vendor that withdrew: ' + d.chosen_vendor_name);
}

// Never trust the model's arithmetic for a number that lands in a financial column.
const chosenCost = Number(d.chosen_cost);
const computed = chosenCost - Number(brief.declined_cost);
const impact = isNaN(computed) ? Number(d.budget_impact) : computed;
const safeImpact = isNaN(impact) ? 0 : impact;

const newBookingId = uuid();
const decisionId = uuid();
const fallbackId = uuid();
const industry = ctx.INDUSTRY;
const declinedVendorId = ctx.VENDOR_ID;

// The approval card is read on a phone, standing up, in about ten seconds. Every
// replacement the agent can pick is CHEAPER than the booking it replaces, so a raw
// '-90' would read as a deficit. Say what it is in words.
const absImpact = Math.abs(safeImpact).toLocaleString();
let impactLabel;
if (safeImpact < 0) { impactLabel = '$' + absImpact + ' saving per unit'; }
else if (safeImpact > 0) { impactLabel = '$' + absImpact + ' increase per unit'; }
else { impactLabel = 'No change in cost'; }

const conf = Number(d.confidence);
const confidencePct = isNaN(conf) ? 'n/a' : Math.round(conf * 100) + '%';

// Every startData field is typed `text` in Nintex, so send pre-formatted strings.
// NOTE se_clientnamr -- that typo is the real variable name in the Nintex design.
const approvalPayload = JSON.stringify({ startData: {
  se_approveremail: APPROVER,
  se_clientnamr: brief.client_name,
  se_originalvendor: brief.declined_vendor,
  se_replacementvendor: d.chosen_vendor_name,
  se_costimpact: impactLabel,
  se_agentconfidence: confidencePct,
  se_agentreasoning: d.reasoning
} });

// AWAITING_APPROVAL, not CONFIRMED. This is the whole point of the beat: the agent
// picks and prices the replacement, then stops. The workspace renders this status in
// navy so the room can see the one row that is waiting on a human.
const sqlBooking = 'INSERT INTO AIGS_DEMO.ONBOARDING.VENDOR_BOOKINGS (booking_id, engagement_id, vendor_id, service_type, booked_at, status, cost, replaced_booking_id) VALUES ('
  + [q(newBookingId), q(brief.engagement_id), q(d.chosen_vendor_id), q(brief.service_type), 'CURRENT_TIMESTAMP()', q('AWAITING_APPROVAL'), num(chosenCost), q(brief.booking_id)].join(', ') + ')';

const actionTaken = 'Re-sourced ' + brief.service_type + ' from ' + brief.declined_vendor
  + ' to ' + d.chosen_vendor_name + ' at $' + Number(chosenCost).toLocaleString()
  + ' per unit, pending human approval';

const sqlDecision = 'INSERT INTO AIGS_DEMO.ONBOARDING.AGENT_DECISIONS (decision_id, engagement_id, trigger_event, reasoning, action_taken, alternatives_considered, confidence, decided_at, human_reviewed) VALUES ('
  + [q(decisionId), q(brief.engagement_id), q('VENDOR_DECLINED'), q(d.reasoning), q(actionTaken),
     q(d.alternatives_considered), num(d.confidence), 'CURRENT_TIMESTAMP()', 'FALSE'].join(', ') + ')';

// --- approve path -------------------------------------------------------------
const sqlConfirm = 'UPDATE AIGS_DEMO.ONBOARDING.VENDOR_BOOKINGS SET status = ' + q('CONFIRMED')
  + ' WHERE booking_id = ' + q(newBookingId);
const sqlBudget = 'UPDATE AIGS_DEMO.ONBOARDING.ENGAGEMENTS SET budget_variance = COALESCE(budget_variance, 0) + ' + num(safeImpact)
  + ' WHERE engagement_id = ' + q(brief.engagement_id);
const sqlReviewed = 'UPDATE AIGS_DEMO.ONBOARDING.AGENT_DECISIONS SET human_reviewed = TRUE WHERE decision_id = ' + q(decisionId);

// --- reject path --------------------------------------------------------------
// Falls back to the next-ranked vendor entirely in SQL. Deliberately NOT a second
// agent call: a wrong tap on stage must recover in one step, not start another
