const sqlReject = 'UPDATE AIGS_DEMO.ONBOARDING.VENDOR_BOOKINGS SET status = ' + q('REJECTED')
  + ' WHERE booking_id = ' + q(newBookingId);

const sqlFallback = 'INSERT INTO AIGS_DEMO.ONBOARDING.VENDOR_BOOKINGS (booking_id, engagement_id, vendor_id, service_type, booked_at, status, cost, replaced_booking_id) SELECT '
  + [q(fallbackId), q(brief.engagement_id), 'v.vendor_id', q(brief.service_type), 'CURRENT_TIMESTAMP()', q('CONFIRMED'), 'v.cost_per_unit', q(brief.booking_id)].join(', ')
  + ' FROM AIGS_DEMO.ONBOARDING.VENDORS v WHERE v.industry = ' + q(industry)
  + ' AND v.service_type = ' + q(brief.service_type) + ' AND v.active = TRUE'
  + ' AND v.vendor_id NOT IN (' + q(declinedVendorId) + ', ' + q(d.chosen_vendor_id) + ')'
  + ' ORDER BY v.rating DESC, v.cost_per_unit ASC LIMIT 1';

// The fallback's cost is not known until the row above exists, so read it back.
const sqlSettle = 'UPDATE AIGS_DEMO.ONBOARDING.ENGAGEMENTS SET budget_variance = COALESCE(budget_variance, 0) + '
  + '(SELECT vb.cost - ' + num(brief.declined_cost) + ' FROM AIGS_DEMO.ONBOARDING.VENDOR_BOOKINGS vb WHERE vb.booking_id = ' + q(fallbackId) + ')'
  + ' WHERE engagement_id = ' + q(brief.engagement_id);

const sqlFallbackDecision = 'INSERT INTO AIGS_DEMO.ONBOARDING.AGENT_DECISIONS (decision_id, engagement_id, trigger_event, reasoning, action_taken, alternatives_considered, confidence, decided_at, human_reviewed) SELECT '
  + [q(uuid()), q(brief.engagement_id), q('APPROVAL_REJECTED'),
     "'A human reviewer declined " + String(d.chosen_vendor_name).replace(/'/g, "''") + " for this " + String(brief.service_type).replace(/'/g, "''") + " booking. The next-ranked available vendor, ' || v.vendor_name || ', was booked instead at $' || TO_VARCHAR(v.cost_per_unit, '999,999.00') || ' per unit.'",
     "'Booked ' || v.vendor_name || ' after human rejection'",
     q('Next-ranked vendor by rating, excluding the withdrawn and the rejected vendor'),
     'NULL', 'CURRENT_TIMESTAMP()', 'TRUE'].join(', ')
  + ' FROM AIGS_DEMO.ONBOARDING.VENDOR_BOOKINGS b JOIN AIGS_DEMO.ONBOARDING.VENDORS v ON v.vendor_id = b.vendor_id WHERE b.booking_id = ' + q(fallbackId);

