const row = $input.first().json || {};
const a = $('Apply Decision').first().json;

const q = (v) => (v === null || v === undefined) ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'";
const num = (v) => (v === null || v === undefined || v === '' || isNaN(Number(v))) ? '0' : String(Number(v));

const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
  const r = Math.random() * 16 | 0;
  const v = c === 'x' ? r : ((r & 0x3) | 0x8);
  return v.toString(16);
});

const vendor = row.VENDOR_NAME || row.vendor_name || 'the next-ranked vendor';
const costRaw = row.COST !== undefined ? row.COST : row.cost;
const cost = Number(costRaw);
const costText = isNaN(cost) ? 'the catalogue rate'
  : '$' + cost.toLocaleString() + ' per unit';

// Written for a projector, same rules as the agent's own reasoning: plain business
// language, no mention of the mechanism.
const reasoning = 'A human reviewer declined ' + a.replacement_vendor + ' for this '
  + a.service_type + ' booking. The next-ranked available vendor, ' + vendor
  + ', was booked instead at ' + costText + '.';

const actionTaken = 'Booked ' + vendor + ' at ' + costText + ' after human rejection';

const sql = 'INSERT INTO AIGS_DEMO.ONBOARDING.AGENT_DECISIONS (decision_id, engagement_id, trigger_event, reasoning, action_taken, alternatives_considered, confidence, decided_at, human_reviewed) VALUES ('
  + [q(uuid()), q(a.engagement_id), q('APPROVAL_REJECTED'), q(reasoning), q(actionTaken),
     q('Next-ranked vendor by rating, excluding the withdrawn vendor and the rejected replacement'),
     'NULL', 'CURRENT_TIMESTAMP()', 'TRUE'].join(', ') + ')';

return [{ json: {
  fallback_vendor: vendor,
  fallback_cost: isNaN(cost) ? null : cost,
  reasoning: reasoning,
  sql: sql
} }];
